const raw = $json.output ?? $json.text ?? $json;
const value = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '')) : raw;
if (!value || typeof value.subject !== 'string' || typeof value.text !== 'string' || typeof value.html !== 'string') {
  throw new Error('AI Agent must return subject, text and html');
}
return [{ json: value }];
